=== KEY DISPATCH-LOOP SOURCE (src/lib.rs Vm::run) ===
pub fn run<const FUEL: bool>(&mut self, code:&[Instr], consts:&[Value], luts:&Luts, fuel_budget:u64) -> Value {
    let mut pc: usize = 0;
    let mut fuel: u64 = fuel_budget;
    let reg = &mut self.reg;
    let arr = &mut self.arr;
    loop {
        let i = unsafe { *code.get_unchecked(pc) };   // fixed-width decode, no two-level decode
        pc += 1;
        if FUEL { fuel = fuel.wrapping_sub(1); if fuel == 0 { return Value::nil(); } }  // deterministic fuel
        let a = i.a as usize;
        match i.op {                                  // ONE big match -> br_table(wasm)/jump-table(native)
            OP_LOADK => { reg[a] = unsafe { *consts.get_unchecked(i.c as usize) }; }
            OP_NMUL  => { reg[a] = Value::num(reg[i.b as usize].as_num() * reg[i.c as usize].as_num()); }
            OP_NMODK => { let k = unsafe { consts.get_unchecked(i.c as usize) }.as_num();
                          reg[a] = Value::num(reg[i.b as usize].as_num() % k); }
            OP_FORNLOOP => {                           // numeric-for superinstruction
                let step = reg[a+2].as_num();
                let idx  = reg[a].as_num() + step; reg[a] = Value::num(idx);
                let limit = reg[a+1].as_num();
                if (if step>0.0 { idx<=limit } else { idx>=limit }) { pc = i.aux as usize; }
            }
            OP_AGET => { let idx = reg[i.b as usize].as_num() as usize; reg[a] = unsafe { *arr.get_unchecked(idx) }; }
            OP_JMPIFNOT => { if !reg[a].truthy() { pc = i.aux as usize; } }
            OP_CALL => { /* host fxmul / curve_kind for the determinism Q16 path */ }
            OP_RET => return reg[a],
            ... (NADD/NSUB/NDIV/NMULK/NLT/NLE/NEQ/NEQK/FORNPREP/JMP/JMPIF/ILT/IEQ/MOVE/HALT)
        }
    }
}
